<?php $productionJobs=makeos_customer_progress_for_order($order['guid']); ?>
<section class="page-hero shell compact"><p class="kicker">Order <?=e($order['number'])?></p><h1><?=e(str_replace('_',' ',ucwords(strtolower($order['status']),'_')))?></h1><p>Placed <?=e(date('d M Y, H:i',strtotime($order['created_at'])))?> · Payment <?=e(strtolower($order['payment_status']))?></p></section><section class="section section-tight shell order-detail-grid"><div><section class="account-panel"><div class="panel-head"><h2>Pieces</h2><span class="status-pill commerce <?=e(strtolower($order['status']))?>"><?=e(str_replace('_',' ',$order['status']))?></span></div><?php foreach($order['items'] as $item):?><article class="order-item"><img src="<?=e(image_url($item['image']))?>" alt=""><div><h3><?=e($item['name'])?></h3><p><?=e($item['material'])?> · <?=e($item['finish'])?> · Qty <?=e((string)$item['qty'])?></p><?php if(!empty($item['configuration_summary'])):?><div class="order-config-summary"><?php foreach(array_slice($item['configuration_summary'],2) as $cs): if(($cs['value']??'')==='Not selected'||($cs['value']??'')==='None')continue;?><span><?=e($cs['label'])?>: <?=e($cs['value'])?></span><?php endforeach;?></div><?php endif;?><small>SKU <?=e($item['sku'])?><?php if(!empty($item['pricing_version'])):?> · Config pricing <?=e($item['pricing_version'])?><?php endif;?></small></div><b><?=money($item['line_total'])?></b></article><?php endforeach;?></section><?php if($productionJobs):?><section class="account-panel"><div class="panel-head"><h2>Workshop progress</h2><small>Customer-safe production status</small></div><div class="customer-job-list"><?php foreach($productionJobs as $pj):?><article><div><strong><?=e($pj['product_name'])?></strong><small><?=e($pj['number'])?> · <?=e($pj['status_label'])?><?php if($pj['stage_label']):?> · <?=e($pj['stage_label'])?><?php endif;?></small></div><b><?=e((string)$pj['progress'])?>%</b><div class="production-progress"><span style="width:<?=e((string)$pj['progress'])?>%"></span></div></article><?php endforeach;?></div></section><?php endif;?><section class="account-panel"><h2>Timeline</h2><div class="timeline"><?php foreach(array_reverse($order['timeline']) as $event):?><div><i></i><div><strong><?=e(str_replace('_',' ',(string)$event['to']))?></strong><small><?=e(date('d M Y, H:i',strtotime($event['ts'])))?><?php if(!empty($event['note'])):?> · <?=e($event['note'])?><?php endif;?></small></div></div><?php endforeach;?></div></section><?php if($requests):?><section class="account-panel"><h2>Requests</h2><?php foreach($requests as $r):?><div class="request-row"><span><?=e($r['type'])?></span><strong><?=e($r['status'])?></strong><small><?=e($r['reason'])?></small></div><?php endforeach;?></section><?php endif;?></div><aside><section class="order-summary elegant"><p class="kicker">Order total</p><div><span>Subtotal</span><b><?=money($order['pricing']['subtotal'])?></b></div><div><span>Delivery</span><b><?=money($order['pricing']['shipping'])?></b></div><?php if($order['pricing']['installation']):?><div><span>Installation</span><b><?=money($order['pricing']['installation'])?></b></div><?php endif;?><div><span>GST included</span><b><?=money($order['pricing']['tax_inclusive'])?></b></div><div class="summary-total"><span>Total</span><strong><?=money($order['pricing']['grand_total'])?></strong></div><?php if(($order['status']??'')==='PENDING_PAYMENT'):?><form method="post" action="<?=e(url('/account/orders/'.$order['guid'].'/pay'))?>"><?=csrf_field()?><button class="btn dark wide" type="submit">Retry sandbox payment</button></form><?php endif;?><?php if(!empty($order['invoice'])):?><a class="btn outline wide" href="<?=e(url('/account/orders/'.$order['guid'].'/invoice'))?>">View invoice</a><?php endif;?></section><section class="account-panel compact-panel"><h3>Delivering to</h3><p><?=e($order['address_snapshot']['name'])?><br><?=e($order['address_snapshot']['line1'])?><br><?=e($order['address_snapshot']['city'])?>, <?=e($order['address_snapshot']['state'])?> <?=e($order['address_snapshot']['pincode'])?></p><small><?=e($order['shipping_snapshot']['eta']??'')?></small></section><?php if(in_array($order['status'],['PENDING_PAYMENT','PAID','CONFIRMED'],true)):?><section class="account-panel compact-panel"><h3>Need to change this order?</h3><form method="post" action="<?=e(url('/account/orders/'.$order['guid'].'/request'))?>" class="commerce-form"><?=csrf_field()?><input type="hidden" name="type" value="CANCELLATION"><label>Reason<textarea name="reason" rows="3" required></textarea></label><button class="btn outline wide" type="submit">Request cancellation</button></form></section><?php elseif(in_array($order['status'],['IN_PRODUCTION','READY_TO_DISPATCH','DELIVERED'],true)):?><section class="account-panel compact-panel"><h3>Request support</h3><form method="post" action="<?=e(url('/account/orders/'.$order['guid'].'/request'))?>" class="commerce-form"><?=csrf_field()?><input type="hidden" name="type" value="REFUND"><label>Reason<textarea name="reason" rows="3" required></textarea></label><button class="btn outline wide" type="submit">Request refund review</button></form></section><?php endif;?></aside></section>
